// SPDX-License-Identifier: GPL-2.0-or-later
// Generator for the Gigabyte RGB Fusion 2 module device table.
// Usage: node scripts/openrgb/port-gigabyte-rgbfusion2-devices.mjs <openrgb-root> <commit>
// Reads GigabyteRGBFusion2USBControllerDetect.cpp and regenerates
// modules/gigabyte-rgbfusion2/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'GigabyteRGBFusion2USBController');
const detect = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /Detect.*\.cpp$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');
const headerText = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /\.h$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');
const constants = Object.fromEntries(
  [...(headerText + detect).matchAll(/#define\s+([A-Za-z][A-Za-z0-9_]*)\s+(0x[0-9A-Fa-f]+|\d+)/g)].map((m) => [
    m[1],
    m[2].startsWith('0x') ? Number.parseInt(m[2], 16) : Number.parseInt(m[2], 10),
  ]),
);
const n = (s) => {
  const t = s.trim();
  if (t in constants) return constants[t];
  if (/^0x[0-9A-Fa-f]+$/.test(t)) return Number.parseInt(t, 16);
  if (/^\d+$/.test(t)) return Number.parseInt(t, 10);
  throw new Error(`unresolved constant ${t}`);
};
const nameDefine = {};

const rows = [];
for (const m of detect.matchAll(
  /#define\s+(DETECTOR_NAME)\s+"([^"]+)"/g,
)) {
  nameDefine[m[1]] = m[2];
}
for (const m of detect.matchAll(/REGISTER_HID_DETECTOR[A-Z_]*\s*\(([^;]*?)\);/g)) {
  const args = m[1]
    .split(',')
    .map((s) => s.trim());
  const nameRaw = args[0];
  const name = nameRaw.startsWith('"')
    ? JSON.parse(nameRaw)
    : nameDefine[nameRaw] ?? nameRaw.replace(/_/g, ' ');
  rows.push({
    name,
    handler: args[1],
    vid: n(args[2]),
    pid: n(args[3]),
    usagePage: n(args[4]),
    usage: n(args[5]),
  });
}
const seen = new Set();
const unique = rows.filter((r) => {
  const k = `${r.name}|${r.pid}`;
  if (seen.has(k)) return false;
  seen.add(k);
  return true;
});
if (unique.length !== 5) throw new Error(`expected 5 HID detectors, got ${unique.length}`);

const out = path.join(process.cwd(), 'modules', 'gigabyte-rgbfusion2', 'src', 'devices_table.rs');
fs.mkdirSync(path.dirname(out), { recursive: true });
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-gigabyte-rgbfusion2-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...unique.map((d) =>
    `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, usage_page: 0x${d.usagePage.toString(16)}, usage: 0x${d.usage.toString(16)} },
`,
  ),
  '];',
  '',
];
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${unique.length} Gigabyte RGB Fusion 2 USB detectors`);